1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strings"
11	
12		"github.com/mattn/go-isatty"
13		"github.com/spf13/cobra"
14	
15		"github.com/ashtom/entire-brain/internal/tui"
16	)
17	
18	// dashDefaultLimit caps how many entries per tab the dashboard loads. Large
19	// brains can hold thousands of facts/symbols; the cap keeps the snapshot bounded
20	// and a Note records what was dropped so the truncation is never silent. A
21	// non-positive --limit means no cap.
22	const dashDefaultLimit = 500
23	
24	// dashSearchLimit caps results from an in-dashboard search (the `s` key),
25	// matching the `entire brain search` default surface.
26	const dashSearchLimit = 25
27	
28	type dashFlags struct {
29		theme  string
30		tab    string
31		branch string
32		limit  int
33		json   bool
34		plain  bool
35	}
36	
37	func newDashCommand(opts Options) *cobra.Command {
38		var flags dashFlags
39		cmd := &cobra.Command{
40			Use:   "dash [path]",
41			Short: "Browse the brain in an interactive dashboard (status, facts, sessions, history, semantic)",
42			Long: `dash opens an interactive terminal dashboard over the brain: a Home tab
43	summarizing source health, freshness, and blind spots, plus explorer tabs that
44	browse individual facts, sessions, history records, and semantic symbols, each
45	with a detail page. It is read-only and makes no agent calls.
46	
47	On a non-TTY (piped output) it prints a plain summary instead; --json emits the
48	loaded snapshot.`,
49			Args: cobra.MaximumNArgs(1),
50			RunE: func(cmd *cobra.Command, args []string) error {
51				return runDash(cmd.Context(), cmd, opts, flags, agentSurfaceTarget(opts, args))
52			},
53		}
54		cmd.Flags().StringVar(&flags.theme, "theme", "", "Color theme: "+strings.Join(tui.ThemeNames(), ", ")+" (or set ENTIRE_BRAIN_THEME)")
55		cmd.Flags().StringVar(&flags.tab, "tab", "", "Tab to open on: home, facts, sessions, history, semantic, search")
56		cmd.Flags().StringVar(&flags.branch, "branch", "", "Branch whose facts to load (default: current branch)")
57		cmd.Flags().IntVar(&flags.limit, "limit", dashDefaultLimit, "Max entries loaded per tab (0 = no cap)")
58		cmd.Flags().BoolVar(&flags.json, "json", false, "Emit the loaded snapshot as JSON instead of opening the dashboard")
59		cmd.Flags().BoolVar(&flags.plain, "plain", false, "Print a plain text summary instead of opening the dashboard")
60		return cmd
61	}
62	
63	func runDash(ctx context.Context, cmd *cobra.Command, opts Options, flags dashFlags, target string) error {
64		startTab, ok := tui.ParseTab(flags.tab)
65		if !ok && flags.tab != "" {
66			return fmt.Errorf("unknown_tab: %q (want home, facts, sessions, history, semantic, or search)", flags.tab)
67		}
68	
69		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, target, flags.branch)
70		if err != nil {
71			return err
72		}
73	
74		snap, err := assembleBrainSnapshot(ctx, opts, target, repoDir, brainDir, branch, flags.limit)
75		if err != nil {
76			return err
77		}
78	
79		if flags.json {
80			return writeJSON(cmd, snap)
81		}
82		if flags.plain || !commandOutputIsTTY(cmd) {
83			printDashPlain(cmd, snap)
84			return nil
85		}
86		return tui.Run(snap, resolveDashTheme(flags.theme), brainSearchFunc(brainDir, branch), startTab, cmd.OutOrStdout())
87	}
88	
89	// brainSearchFunc adapts the lexical retrieval (`entire brain search`) into the
90	// callback the dashboard's `s` key invokes, so search runs the same code path as
91	// the CLI verb while keeping the TUI free of file IO.
92	func brainSearchFunc(brainDir, branch string) tui.SearchFunc {
93		return func(query string) ([]tui.SearchResult, error) {
94			results, err := retrieveUnified(brainDir, branch, query, dashSearchLimit, modeLexical)
95			if err != nil {
96				return nil, err
97			}
98			out := make([]tui.SearchResult, 0, len(results))
99			for _, r := range results {
100				out = append(out, searchResultFromUnified(r, brainDir))
101			}
102			return out, nil
103		}
104	}
105	
106	// searchResultFromUnified maps a retrieval hit to the TUI view model and decides
107	// its "open source" target. Only history and doc hits carry a real
108	// brain-relative file path; a fact's Path is its taxonomy labels (not a file),
109	// so a fact hit gets no open target rather than a bogus one.
110	func searchResultFromUnified(r unifiedResult, brainDir string) tui.SearchResult {
111		sr := tui.SearchResult{
112			Source:  r.Source,
113			ID:      r.ID,
114			Path:    r.Path,
115			Heading: r.Heading,
116			Line:    r.Line,
117			Text:    r.Text,
118			Score:   r.Score,
119		}
120		if r.Path != "" && (r.Source == "history" || r.Source == "doc") {
121			sr.OpenPath = containedPath(brainDir, r.Path)
122			sr.OpenLine = r.Line
123		}
124		return sr
125	}
126	
127	// assembleBrainSnapshot is the only place that touches the brain on disk. It
128	// reuses the existing loaders to build a read-only tui.Snapshot; no agent calls.
129	func assembleBrainSnapshot(ctx context.Context, opts Options, target, repoDir, brainDir, branch string, limit int) (tui.Snapshot, error) {
130		snap := tui.Snapshot{Repo: repoDir, Branch: branch}
131	
132		status, err := buildBrainStatusReport(ctx, opts, target)
133		if err != nil {
134			return snap, err
135		}
136		if status.Repo.Root != "" {
137			snap.Repo = status.Repo.Root
138		}
139		snap.GeneratedAt = status.Brain.GeneratedAt
140		manifest := status.Manifest
141		snap.Home = dashHomeView(status, manifest, branch)
142	
143		// Facts (per branch).
144		if facts, err := loadFacts(brainDir, branch); err != nil {
145			snap.Home.Warnings = append(snap.Home.Warnings, "facts unavailable: "+err.Error())
146		} else {
147			snap.Facts = dashFactViews(facts, brainDir, limit)
148			snap.Notes = appendCapNote(snap.Notes, "facts", len(facts), len(snap.Facts))
149		}
150	
151		if manifest != nil && manifest.Sources != nil {
152			// Sessions (from the manifest).
153			if s := manifest.Sources.Sessions; s != nil {
154				snap.Sessions = dashSessionViews(s.Sessions, brainDir, limit)
155				snap.Notes = appendCapNote(snap.Notes, "sessions", len(s.Sessions), len(snap.Sessions))
156			}
157			// History (index.json).
158			if h := manifest.Sources.History; h != nil {
159				if idx, err := loadBrainHistoryIndex(brainDir, h); err != nil {
160					snap.Home.Warnings = append(snap.Home.Warnings, "history unavailable: "+err.Error())
161				} else {
162					snap.History = dashHistoryViews(idx.Records, brainDir, limit)
163					snap.Notes = appendCapNote(snap.Notes, "history", len(idx.Records), len(snap.History))
164				}
165			}
166			// Semantic symbols (snapshot.ndjson).
167			if sem := manifest.Sources.Semantic; sem != nil {
168				if syms, err := loadSemanticSymbols(brainDir, sem, limit); err != nil {
169					snap.Home.Warnings = append(snap.Home.Warnings, "semantic unavailable: "+err.Error())
170				} else {
171					snap.Semantic = dashSemanticViews(syms, repoDir)
172					snap.Notes = appendCapNote(snap.Notes, "semantic symbols", sem.Symbols, len(snap.Semantic))
173				}
174			}
175		}
176	
177		return snap, nil
178	}
179	
180	// dashHomeView maps the status report into the Home tab view model.
181	func dashHomeView(status brainStatusReport, manifest *exportManifest, branch string) tui.HomeView {
182		home := tui.HomeView{
183			Freshness:  brainStatusFreshnessSeverity(status),
184			Warnings:   append([]string(nil), status.Warnings...),
185			BlindSpots: dashBlindSpotLabels(brainStatusBlindSpots(status)),
186		}
187	
188		present := status.Sources
189		detail := dashSourceDetails(manifest)
190		home.Sources = []tui.SourceHealth{
191			{Name: "Seed", Present: present.Seed, Detail: detail["seed"]},
192			{Name: "Sessions", Present: present.Sessions, Detail: detail["sessions"]},
193			{Name: "Semantic", Present: present.Semantic, Detail: detail["semantic"]},
194			{Name: "History", Present: present.History, Detail: detail["history"]},
195			{Name: "Facts", Present: present.Facts, Detail: detail["facts"]},
196		}
197	
198		if status.Semantic != nil && status.Semantic.Freshness != nil {
199			for name, axis := range status.Semantic.Freshness.Axes {
200				home.Axes = append(home.Axes, tui.FreshnessAxis{Name: name, State: axis.State, Detail: axis.Detail})
201			}
202			sortFreshnessAxes(home.Axes)
203		}
204	
205		home.Live = tui.LiveState{
206			Branch:  firstNonEmpty(status.Live.Branch, branch),
207			Head:    status.Live.Head,
208			Dirty:   status.Live.Dirty,
209			Summary: dashLiveSummary(status.Live),
210		}
211	
212		if manifest != nil && manifest.GeneratedAt.IsZero() && !anySource(present) {
213			home.Warnings = append(home.Warnings, "brain not built yet — run `entire brain refresh`")
214		}
215		return home
216	}
217	
218	func dashSourceDetails(manifest *exportManifest) map[string]string {
219		out := map[string]string{}
220		if manifest == nil || manifest.Sources == nil {
221			return out
222		}
223		src := manifest.Sources
224		if s := src.Sessions; s != nil {
225			out["sessions"] = fmt.Sprintf("%d sessions · %d checkpoints scanned", len(s.Sessions), s.CheckpointsScanned)
226		}
227		if s := src.Semantic; s != nil {
228			out["semantic"] = fmt.Sprintf("%d symbols · %d relations · %d files", s.Symbols, s.Relations, s.Files)
229		}
230		if h := src.History; h != nil {
231			out["history"] = fmt.Sprintf("%d records (%d decisions · %d learnings)", h.Records, h.Decisions, h.Learnings)
232		}
233		if f := src.Facts; f != nil {
234			out["facts"] = fmt.Sprintf("%d facts across %d branch(es)", f.Facts, len(f.Branches))
235		}
236		if s := src.Seed; s != nil {
237			out["seed"] = fmt.Sprintf("%d entrypoints · %d commands", len(s.Entrypoints), len(s.Commands))
238		}
239		return out
240	}
241	
242	func dashBlindSpotLabels(spots []brainBlindSpot) []string {
243		if len(spots) == 0 {
244			return nil
245		}
246		out := make([]string, 0, len(spots))
247		for _, s := range spots {
248			label := s.Detail
249			if label == "" {
250				label = s.Code
251			}
252			if s.Path != "" {
253				if label == "" {
254					label = s.Path
255				} else {
256					label = s.Path + ": " + label
257				}
258			}
259			if label == "" {
260				continue
261			}
262			out = append(out, label)
263		}
264		return out
265	}
266	
267	func dashLiveSummary(live brainLiveState) string {
268		if !live.Dirty {
269			return "clean"
270		}
271		parts := make([]string, 0, 3)
272		if n := len(live.Staged); n > 0 {
273			parts = append(parts, fmt.Sprintf("%d staged", n))
274		}
275		if n := len(live.Unstaged); n > 0 {
276			parts = append(parts, fmt.Sprintf("%d unstaged", n))
277		}
278		if n := len(live.Untracked); n > 0 {
279			parts = append(parts, fmt.Sprintf("%d untracked", n))
280		}
281		if len(parts) == 0 {
282			return "dirty"
283		}
284		return strings.Join(parts, " · ")
285	}
286	
287	func dashFactViews(facts []factRecord, brainDir string, limit int) []tui.FactView {
288		if limit > 0 && len(facts) > limit {
289			facts = facts[:limit]
290		}
291		out := make([]tui.FactView, 0, len(facts))
292		for _, f := range facts {
293			view := tui.FactView{
294				ID:         f.ID,
295				Kind:       f.Kind,
296				Text:       f.Text,
297				Paths:      f.Paths,
298				Locus:      f.Locus,
299				Status:     f.Status,
300				Origin:     f.Origin,
301				Confidence: f.Confidence,
302				Related:    f.RelatedIDs,
303			}
304			for _, a := range f.Provenance {
305				view.Provenance = append(view.Provenance, tui.Anchor{
306					SessionID:  a.SessionID,
307					Commit:     a.Commit,
308					Transcript: a.Transcript,
309					Line:       a.Line,
310					Verified:   a.Verified,
311				})
312			}
313			if len(f.Provenance) > 0 && f.Provenance[0].Transcript != "" {
314				view.Source = containedPath(brainDir, f.Provenance[0].Transcript)
315				view.SourceLine = f.Provenance[0].Line
316			}
317			out = append(out, view)
318		}
319		return out
320	}
321	
322	func dashSessionViews(sessions []exportSession, brainDir string, limit int) []tui.SessionView {
323		if limit > 0 && len(sessions) > limit {
324			sessions = sessions[:limit]
325		}
326		out := make([]tui.SessionView, 0, len(sessions))
327		for _, s := range sessions {
328			view := tui.SessionView{
329				ID:          s.SessionID,
330				Branch:      s.Branch,
331				Agent:       s.Agent,
332				Model:       s.Model,
333				Kind:        s.Kind,
334				Files:       s.FilesTouched,
335				Checkpoints: s.CheckpointsCount,
336			}
337			if !s.CreatedAt.IsZero() {
338				view.Created = s.CreatedAt.UTC().Format("2006-01-02 15:04Z")
339			}
340			if s.TokenUsage != nil {
341				view.InputTok = s.TokenUsage.InputTokens
342				view.OutputTok = s.TokenUsage.OutputTokens
343			}
344			if s.Summary != nil {
345				view.Intent = s.Summary.Intent
346				view.Outcome = s.Summary.Outcome
347			}
348			if s.TranscriptPath != "" {
349				view.Source = containedPath(brainDir, s.TranscriptPath)
350			}
351			out = append(out, view)
352		}
353		return out
354	}
355	
356	func dashHistoryViews(records []historyRecord, brainDir string, limit int) []tui.HistoryView {
357		if limit > 0 && len(records) > limit {
358			records = records[:limit]
359		}
360		out := make([]tui.HistoryView, 0, len(records))
361		for _, r := range records {
362			view := tui.HistoryView{
363				ID:      r.ID,
364				Kind:    r.Kind,
365				Branch:  r.Branch,
366				Summary: r.Summary,
367				Path:    r.Path,
368				Line:    r.Line,
369			}
370			if r.Path != "" {
371				view.Source = containedPath(brainDir, r.Path)
372				view.SourceLine = r.Line
373			}
374			out = append(out, view)
375		}
376		return out
377	}
378	
379	func dashSemanticViews(syms []semanticRecord, repoDir string) []tui.SemanticView {
380		out := make([]tui.SemanticView, 0, len(syms))
381		for _, s := range syms {
382			view := tui.SemanticView{
383				Kind:          s.Kind,
384				Name:          s.Name,
385				QualifiedName: s.QualifiedName,
386				FilePath:      s.FilePath,
387				StartLine:     s.StartLine,
388				EndLine:       s.EndLine,
389				Signature:     s.Signature,
390				Language:      s.Language,
391			}
392			// Contain the snapshot-provided path: a tampered snapshot must not make
393			// `o` open a file outside the repo (absolute / traversal paths rejected).
394			if repoDir != "" {
395				if src := containedPath(repoDir, s.FilePath); src != "" {
396					view.Source = src
397					view.SourceLine = s.StartLine
398				}
399			}
400			out = append(out, view)
401		}
402		return out
403	}
404	
405	// loadSemanticSymbols reads the symbol records from the active semantic snapshot
406	// (NDJSON: a header line followed by one record per line), reusing the snapshot
407	// scanner and path validation. A missing snapshot yields no symbols.
408	func loadSemanticSymbols(brainDir string, source *semanticSourceManifest, limit int) ([]semanticRecord, error) {
409		if source == nil || source.SnapshotPath == "" {
410			return nil, nil
411		}
412		rel, err := validateSemanticSnapshotPath(source.SnapshotPath)
413		if err != nil {
414			return nil, err
415		}
416		full := filepath.Join(brainDir, rel)
417		// A missing snapshot is not an error: an inconsistent or not-yet-built brain
418		// just yields no symbols rather than a scary warning.
419		if _, statErr := os.Stat(full); os.IsNotExist(statErr) {
420			return nil, nil
421		}
422		if err := rejectSymlinkPathComponents(brainDir, rel); err != nil {
423			return nil, err
424		}
425		f, err := os.Open(full)
426		if err != nil {
427			if os.IsNotExist(err) {
428				return nil, nil
429			}
430			return nil, err
431		}
432		defer f.Close()
433		scanner := newSemanticScanner(f)
434		first := true
435		var out []semanticRecord
436		for scanner.Scan() {
437			if first { // skip the header line
438				first = false
439				continue
440			}
441			text := bytes.TrimSpace(scanner.Bytes())
442			if len(text) == 0 {
443				continue
444			}
445			var rec semanticRecord
446			if err := json.Unmarshal(text, &rec); err != nil {
447				return nil, err
448			}
449			if rec.RecordType != "symbol" {
450				continue
451			}
452			out = append(out, rec)
453			if limit > 0 && len(out) >= limit {
454				break
455			}
456		}
457		return out, scanner.Err()
458	}
459	
460	// printDashPlain renders the snapshot as plain text for non-TTY / --plain use,
461	// reusing the brain summary shape.
462	func printDashPlain(cmd *cobra.Command, snap tui.Snapshot) {
463		out := cmd.OutOrStdout()
464		fmt.Fprintf(out, "Brain dashboard — %s (branch %s)\n", orEmpty(snap.Repo), orEmpty(snap.Branch))
465		if snap.GeneratedAt != "" {
466			fmt.Fprintf(out, "built: %s\n", snap.GeneratedAt)
467		}
468		fmt.Fprintln(out, "\nSources")
469		for _, s := range snap.Home.Sources {
470			mark := "absent"
471			if s.Present {
472				mark = "present"
473			}
474			line := fmt.Sprintf("  %-9s %s", s.Name, mark)
475			if s.Detail != "" {
476				line += "  (" + s.Detail + ")"
477			}
478			fmt.Fprintln(out, line)
479		}
480		if snap.Home.Freshness != "" {
481			fmt.Fprintf(out, "freshness: %s\n", snap.Home.Freshness)
482		}
483		fmt.Fprintf(out, "\nFacts (%d) · Sessions (%d) · History (%d) · Semantic (%d)\n",
484			len(snap.Facts), len(snap.Sessions), len(snap.History), len(snap.Semantic))
485		for _, bs := range snap.Home.BlindSpots {
486			fmt.Fprintf(out, "  blind spot: %s\n", bs)
487		}
488		for _, w := range snap.Home.Warnings {
489			fmt.Fprintf(out, "  warning: %s\n", w)
490		}
491		for _, n := range snap.Notes {
492			fmt.Fprintf(out, "  note: %s\n", n)
493		}
494	}
495	
496	// resolveDashTheme picks the theme from the --theme flag, falling back to
497	// ENTIRE_BRAIN_THEME, then the default scheme.
498	func resolveDashTheme(flagValue string) tui.Theme {
499		name := flagValue
500		if name == "" {
501			name = os.Getenv("ENTIRE_BRAIN_THEME")
502		}
503		theme, _ := tui.ThemeByName(name)
504		return theme
505	}
506	
507	// commandOutputIsTTY reports whether the command's stdout is a terminal.
508	func commandOutputIsTTY(cmd *cobra.Command) bool {
509		if f, ok := cmd.OutOrStdout().(*os.File); ok {
510			return isatty.IsTerminal(f.Fd()) || isatty.IsCygwinTerminal(f.Fd())
511		}
512		return false
513	}
514	
515	// --- small helpers ---------------------------------------------------------
516	
517	// containedPath joins a relative path to a base dir, returning "" for an empty,
518	// absolute, rooted, or escaping path. Path values come straight out of on-disk
519	// brain/snapshot files, so a "../"-laden or rooted value must never resolve to an
520	// open target outside the base (the `o` key hands the result to the OS opener).
521	func containedPath(base, rel string) string {
522		// Reject absolute and rooted paths. filepath.IsAbs is OS-specific (on Windows
523		// a leading-slash path like "/etc/passwd" is NOT absolute), so also reject a
524		// leading "/" or "\" explicitly — a rooted path is never a valid relative
525		// anchor on any platform.
526		if rel == "" || filepath.IsAbs(rel) || strings.HasPrefix(rel, "/") || strings.HasPrefix(rel, `\`) {
527			return ""
528		}
529		clean := filepath.Clean(filepath.FromSlash(rel))
530		if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
531			return ""
532		}
533		full := filepath.Join(base, clean)
534		if r, err := filepath.Rel(base, full); err != nil || r == ".." || strings.HasPrefix(r, ".."+string(filepath.Separator)) {
535			return ""
536		}
537		return full
538	}
539	
540	func appendCapNote(notes []string, label string, total, shown int) []string {
541		if total > shown {
542			return append(notes, fmt.Sprintf("%s: showing %d of %d", label, shown, total))
543		}
544		return notes
545	}
546	
547	func firstNonEmpty(values ...string) string {
548		for _, v := range values {
549			if strings.TrimSpace(v) != "" {
550				return v
551			}
552		}
553		return ""
554	}
555	
556	func anySource(s brainStatusSources) bool {
557		return s.Seed || s.Sessions || s.Semantic || s.History || s.Facts
558	}
559	
560	func orEmpty(v string) string {
561		if v == "" {
562			return "(unknown)"
563		}
564		return v
565	}
566	
567	func sortFreshnessAxes(axes []tui.FreshnessAxis) {
568		for i := 1; i < len(axes); i++ {
569			for j := i; j > 0 && axes[j-1].Name > axes[j].Name; j-- {
570				axes[j-1], axes[j] = axes[j], axes[j-1]
571			}
572		}
573	}
