41	func runBrainAdd(cmd *cobra.Command, opts Options, flags addFlags, repoURL string) error {
42		ctx := cmd.Context()
43		out := cmd.OutOrStdout()
44		errOut := cmd.ErrOrStderr()
45	
46		name := repoDirName(repoURL)
47		if name == "" || name == "." || name == ".." || strings.ContainsAny(name, `/\`) {
48			return fmt.Errorf("invalid_repo_url: cannot derive a safe directory name from %q", repoURL)
49		}
50		if strings.HasPrefix(repoURL, "-") {
51			return fmt.Errorf("invalid_repo_url: %q must not start with '-'", repoURL)
52		}
53		dest := filepath.Join(flags.dir, name)
54	
55		// 1. Clone (skip if the checkout already exists).
56		if isGitCheckout(dest) {
57			fmt.Fprintf(out, "clone: %s already present, skipping\n", dest)
58		} else {
59			fmt.Fprintf(out, "clone: %s -> %s\n", repoURL, dest)
60			// "--" ends option parsing so a repo URL can never be read as a git flag.
61			if _, stderr, err := opts.Runner.Run(ctx, "", "git", "clone", "--quiet", "--", repoURL, dest); err != nil {
62				return fmt.Errorf("clone_failed: %v: %s", err, strings.TrimSpace(string(stderr)))
63			}
64		}
65	
66		// 2. Fetch the Entire checkpoint history (best-effort: a repo may have none).
67		if _, stderr, err := opts.Runner.Run(ctx, dest, "git", "fetch", "--quiet", "origin", "refs/heads/entire/*:refs/heads/entire/*"); err != nil {
68			fmt.Fprintf(errOut, "note: no Entire history fetched (%v): %s\n", err, strings.TrimSpace(string(stderr)))
69		}
