package tui

import (
	"fmt"
	"path"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// renderDetail renders the detail page for the selected entry on a tab. width is
// the content width inside the detail viewport. All content is deterministic —
// it only formats data already present in the snapshot.
func renderDetail(th Theme, s Snapshot, tab Tab, idx, width int) string {
	if width < 20 {
		width = 20
	}
	switch tab {
	case TabHome:
		return renderHome(th, s, width)
	case TabFacts:
		if idx >= 0 && idx < len(s.Facts) {
			return renderFact(th, s.Facts[idx], width)
		}
	case TabSessions:
		if idx >= 0 && idx < len(s.Sessions) {
			return renderSession(th, s.Sessions[idx], width)
		}
	case TabHistory:
		if idx >= 0 && idx < len(s.History) {
			return renderHistory(th, s.History[idx], width)
		}
	case TabSemantic:
		if idx >= 0 && idx < len(s.Semantic) {
			return renderSemantic(th, s.Semantic[idx], width)
		}
	case TabSearch:
		if idx >= 0 && idx < len(s.Search) {
			return renderSearchResult(th, s.Search[idx], width)
		}
		return renderSearchEmpty(th, s)
	}
	return th.dimStyle().Render("Nothing to show in this section.")
}

// renderSearchEmpty is the Search tab's detail when there are no results: a
// prompt to search, or the last query's "no results"/error state.
func renderSearchEmpty(th Theme, s Snapshot) string {
	var b strings.Builder
	b.WriteString(sectionHeader(th, "Search"))
	b.WriteString("\n")
	if s.SearchErr != "" {
		b.WriteString("  " + th.flagStyle().Render("⚠ "+s.SearchErr) + "\n\n")
	} else if s.SearchQuery != "" {
		b.WriteString("  " + th.dimStyle().Render(fmt.Sprintf("no results for %q", s.SearchQuery)) + "\n\n")
	}
	b.WriteString(th.textStyle().Render("  Press ") + th.titleStyle().Render("s") +
		th.textStyle().Render(" to search facts, history, and docs."))
	b.WriteString("\n")
	return b.String()
}

func renderSearchResult(th Theme, r SearchResult, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	b.WriteString(th.titleStyle().Render(orDash(r.Source)))
	if r.Score > 0 {
		b.WriteString(th.dimStyle().Render(fmt.Sprintf("  score %.3f", r.Score)))
	}
	b.WriteString("\n")
	b.WriteString(th.dimStyle().Render(r.ID))
	b.WriteString("\n")
	if r.Path != "" {
		ref := r.Path
		if r.Line > 0 {
			ref += fmt.Sprintf(":%d", r.Line)
		}
		b.WriteString(th.dimStyle().Render(truncate(ref, width)))
		b.WriteString("\n")
	}
	b.WriteString("\n")

	if r.Heading != "" {
		b.WriteString(th.headingStyle().Render(truncate(r.Heading, width)))
		b.WriteString("\n")
	}
	b.WriteString(sectionHeader(th, "Match"))
	b.WriteString("\n")
	b.WriteString(wrap.Render(th.textStyle().Render(r.Text)))
	b.WriteString("\n\n")

	writeOpenHint(&b, th, r.OpenPath)
	return b.String()
}

func renderHome(th Theme, s Snapshot, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	b.WriteString(th.titleStyle().Render(orDash(s.Repo)))
	b.WriteString("\n")
	meta := "branch " + orDash(s.Branch)
	if s.GeneratedAt != "" {
		meta += " · built " + s.GeneratedAt
	}
	b.WriteString(th.dimStyle().Render(truncate(meta, width)))
	b.WriteString("\n\n")

	b.WriteString(sectionHeader(th, "Sources"))
	b.WriteString("\n")
	for _, src := range s.Home.Sources {
		dot := "○"
		color := th.Bad
		if src.Present {
			dot, color = "●", th.Good
		}
		line := lipgloss.NewStyle().Foreground(color).Render("  "+dot+" ") +
			th.textStyle().Render(fmt.Sprintf("%-9s", src.Name))
		if src.Detail != "" {
			line += "  " + th.dimStyle().Render(src.Detail)
		}
		// MaxWidth measures display width and ignores ANSI escapes; truncate()
		// (runewidth) would count the escape bytes and eat the visible text.
		b.WriteString(lipgloss.NewStyle().MaxWidth(width).Render(line))
		b.WriteString("\n")
	}
	b.WriteString("\n")

	if s.Home.Freshness != "" || len(s.Home.Axes) > 0 {
		b.WriteString(sectionHeader(th, "Freshness"))
		b.WriteString("\n")
		if s.Home.Freshness != "" {
			b.WriteString("  " + lipgloss.NewStyle().Foreground(th.healthColor(s.Home.Freshness)).Render(s.Home.Freshness) + "\n")
		}
		for _, ax := range s.Home.Axes {
			line := "    " + ax.Name + ": " + ax.State
			if ax.Detail != "" {
				line += " (" + ax.Detail + ")"
			}
			b.WriteString(th.dimStyle().Render(truncate(line, width)) + "\n")
		}
		b.WriteString("\n")
	}

	if s.Home.Live.Branch != "" || s.Home.Live.Head != "" || s.Home.Live.Summary != "" {
		b.WriteString(sectionHeader(th, "Working tree"))
		b.WriteString("\n")
		state := "clean"
		color := th.Good
		if s.Home.Live.Dirty {
			state, color = orDash(s.Home.Live.Summary), th.OK
		}
		b.WriteString("  " + th.dimStyle().Render("branch: ") + th.textStyle().Render(orDash(s.Home.Live.Branch)) + "\n")
		if s.Home.Live.Head != "" {
			b.WriteString("  " + th.dimStyle().Render("head: ") + th.textStyle().Render(shortID(s.Home.Live.Head)) + "\n")
		}
		b.WriteString("  " + th.dimStyle().Render("status: ") + lipgloss.NewStyle().Foreground(color).Render(state) + "\n\n")
	}

	if len(s.Home.BlindSpots) > 0 {
		b.WriteString(sectionHeader(th, "Blind spots"))
		b.WriteString("\n")
		for _, bs := range s.Home.BlindSpots {
			b.WriteString(wrap.Render("  " + th.flagStyle().Render("• "+bs)))
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	writeWarnings(&b, th, wrap, s.Home.Warnings)
	writeNotes(&b, th, s.Notes)
	return b.String()
}

func renderFact(th Theme, f FactView, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	head := orDash(f.Kind)
	if f.Status != "" {
		head += "  " + statusBadge(th, f.Status)
	}
	b.WriteString(th.titleStyle().Render(head))
	b.WriteString("\n")
	if len(f.Paths) > 0 {
		b.WriteString(th.dimStyle().Render(truncate(strings.Join(f.Paths, " · "), width)))
		b.WriteString("\n")
	}
	b.WriteString(th.dimStyle().Render(f.ID))
	b.WriteString("\n\n")

	b.WriteString(sectionHeader(th, "Fact"))
	b.WriteString("\n")
	b.WriteString(wrap.Render(th.textStyle().Render(f.Text)))
	b.WriteString("\n\n")

	b.WriteString(sectionHeader(th, "Details"))
	b.WriteString("\n")
	metric(&b, th, "origin", orDash(f.Origin))
	if f.Confidence != "" {
		metric(&b, th, "confidence", f.Confidence)
	}
	if len(f.Locus) > 0 {
		metric(&b, th, "locus", strings.Join(f.Locus, ", "))
	}
	if len(f.Related) > 0 {
		metric(&b, th, "related", strings.Join(f.Related, ", "))
	}
	b.WriteString("\n")

	if len(f.Provenance) > 0 {
		b.WriteString(sectionHeader(th, "Provenance"))
		b.WriteString("\n")
		for _, a := range f.Provenance {
			line := "  ↳ "
			if a.SessionID != "" {
				line += "session " + shortID(a.SessionID)
			}
			if a.Commit != "" {
				line += " · " + shortID(a.Commit)
			}
			if a.Transcript != "" {
				ref := a.Transcript
				if a.Line > 0 {
					ref += fmt.Sprintf(":%d", a.Line)
				}
				line += " · " + ref
			}
			if a.Verified {
				line += " ✓"
			}
			b.WriteString(th.dimStyle().Render(truncate(line, width)))
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	writeOpenHint(&b, th, f.Source)
	return b.String()
}

func renderSession(th Theme, v SessionView, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	b.WriteString(th.titleStyle().Render(orDash(v.Agent)))
	if v.Model != "" {
		b.WriteString(th.dimStyle().Render("  (" + v.Model + ")"))
	}
	b.WriteString("\n")
	meta := orDash(v.Created)
	if v.Branch != "" {
		meta += " · " + v.Branch
	}
	if v.Kind != "" {
		meta += " · " + v.Kind
	}
	b.WriteString(th.dimStyle().Render(truncate(meta, width)))
	b.WriteString("\n")
	b.WriteString(th.dimStyle().Render(truncate(v.ID, width)))
	b.WriteString("\n\n")

	if v.Intent != "" || v.Outcome != "" {
		b.WriteString(sectionHeader(th, "Summary"))
		b.WriteString("\n")
		if v.Intent != "" {
			b.WriteString(wrap.Render(th.dimStyle().Render("intent: ") + th.textStyle().Render(v.Intent)))
			b.WriteString("\n")
		}
		if v.Outcome != "" {
			b.WriteString(wrap.Render(th.dimStyle().Render("outcome: ") + th.textStyle().Render(v.Outcome)))
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	b.WriteString(sectionHeader(th, "Activity"))
	b.WriteString("\n")
	metric(&b, th, "checkpoints", fmt.Sprintf("%d", v.Checkpoints))
	metric(&b, th, "files touched", fmt.Sprintf("%d", len(v.Files)))
	if v.InputTok > 0 || v.OutputTok > 0 {
		metric(&b, th, "tokens", fmt.Sprintf("%d in / %d out", v.InputTok, v.OutputTok))
	}
	b.WriteString("\n")

	if len(v.Files) > 0 {
		b.WriteString(sectionHeader(th, "Files"))
		b.WriteString("\n")
		for _, f := range v.Files {
			b.WriteString(th.dimStyle().Render(truncate("  "+f, width)))
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	writeOpenHint(&b, th, v.Source)
	return b.String()
}

func renderHistory(th Theme, h HistoryView, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	b.WriteString(th.titleStyle().Render(orDash(h.Kind)))
	b.WriteString("\n")
	if h.Branch != "" {
		b.WriteString(th.dimStyle().Render("branch " + h.Branch))
		b.WriteString("\n")
	}
	ref := h.Path
	if h.Line > 0 {
		ref += fmt.Sprintf(":%d", h.Line)
	}
	b.WriteString(th.dimStyle().Render(truncate(ref, width)))
	b.WriteString("\n\n")

	b.WriteString(sectionHeader(th, "Summary"))
	b.WriteString("\n")
	b.WriteString(wrap.Render(th.textStyle().Render(orDash(h.Summary))))
	b.WriteString("\n\n")

	writeOpenHint(&b, th, h.Source)
	return b.String()
}

func renderSemantic(th Theme, v SemanticView, width int) string {
	wrap := lipgloss.NewStyle().Width(width).Foreground(th.Text)
	var b strings.Builder

	b.WriteString(th.titleStyle().Render(orDash(v.Name)))
	b.WriteString(th.dimStyle().Render("  " + orDash(v.Kind)))
	b.WriteString("\n")
	if v.QualifiedName != "" && v.QualifiedName != v.Name {
		b.WriteString(th.dimStyle().Render(truncate(v.QualifiedName, width)))
		b.WriteString("\n")
	}
	loc := v.FilePath
	if v.StartLine > 0 {
		loc += fmt.Sprintf(":%d", v.StartLine)
	}
	b.WriteString(th.dimStyle().Render(truncate(loc, width)))
	b.WriteString("\n\n")

	b.WriteString(sectionHeader(th, "Details"))
	b.WriteString("\n")
	if v.Language != "" {
		metric(&b, th, "language", v.Language)
	}
	if v.StartLine > 0 {
		span := fmt.Sprintf("%d", v.StartLine)
		if v.EndLine > v.StartLine {
			span = fmt.Sprintf("%d–%d", v.StartLine, v.EndLine)
		}
		metric(&b, th, "lines", span)
	}
	b.WriteString("\n")

	if v.Signature != "" {
		b.WriteString(sectionHeader(th, "Signature"))
		b.WriteString("\n")
		b.WriteString(wrap.Render(th.textStyle().Render(v.Signature)))
		b.WriteString("\n\n")
	}

	writeOpenHint(&b, th, v.Source)
	return b.String()
}

// --- small render helpers --------------------------------------------------

func sectionHeader(th Theme, title string) string {
	return th.headingStyle().Render("▌ " + title)
}

func metric(b *strings.Builder, th Theme, label, value string) {
	b.WriteString("  " + th.dimStyle().Render(label+": ") + th.textStyle().Render(value) + "\n")
}

func statusBadge(th Theme, status string) string {
	style := th.textStyle()
	switch status {
	case "active":
		style = lipgloss.NewStyle().Foreground(th.Good)
	case "superseded", "retracted":
		style = th.flagStyle()
	}
	return style.Render(status)
}

func writeWarnings(b *strings.Builder, th Theme, wrap lipgloss.Style, warnings []string) {
	if len(warnings) == 0 {
		return
	}
	b.WriteString(sectionHeader(th, "Warnings"))
	b.WriteString("\n")
	for _, w := range warnings {
		b.WriteString(wrap.Render("  " + th.flagStyle().Render("⚠ "+w)))
		b.WriteString("\n")
	}
	b.WriteString("\n")
}

func writeNotes(b *strings.Builder, th Theme, notes []string) {
	for _, n := range notes {
		b.WriteString(th.dimStyle().Render(truncate("· "+n, 200)))
		b.WriteString("\n")
	}
}

func writeOpenHint(b *strings.Builder, th Theme, source string) {
	if source == "" {
		return
	}
	// Render the source as an OSC 8 hyperlink (cmd/ctrl-click in supporting
	// terminals) and note the `o` keybinding, which is the reliable opener when
	// mouse capture keeps the terminal from delivering clicks to the link. The
	// link is written raw — OSC 8 escapes are zero-width, so it must not pass
	// through a width-constrained style.
	link := osc8(fileURL(source), th.linkStyle().Render("↗ open source"))
	b.WriteString(link + th.dimStyle().Render("   (press o)"))
	b.WriteString("\n")
}

// orDash returns value or an em dash when empty.
func orDash(value string) string {
	if strings.TrimSpace(value) == "" {
		return "—"
	}
	return value
}

// oneLine collapses internal newlines/whitespace runs to single spaces for a
// table-cell preview.
func oneLine(value string) string {
	return strings.Join(strings.Fields(value), " ")
}

// shortID trims a long id/hash to its first 12 characters for display.
func shortID(id string) string {
	if len(id) <= 12 {
		return id
	}
	return id[:12]
}

// baseName returns the final path segment of a slash path (the file name).
func baseName(p string) string {
	if p == "" {
		return "—"
	}
	return path.Base(p)
}

package tui

import (
	"fmt"

	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/lipgloss"
)

// newBrainTable builds the left-pane table, themed and focused. It starts with
// placeholder columns so rows can be set before the first resize (which
// recomputes the real widths); the table panics rendering rows against zero
// columns otherwise.
func newBrainTable(th Theme) table.Model {
	t := table.New(table.WithFocused(true), table.WithColumns(columnsFor(TabHome, 36)))
	s := table.DefaultStyles()
	s.Header = s.Header.
		Foreground(th.Dim).
		BorderStyle(lipgloss.NormalBorder()).
		BorderForeground(th.Border).
		BorderBottom(true).
		Bold(false)
	s.Selected = s.Selected.
		Foreground(lipgloss.Color("0")).
		Background(th.Accent).
		Bold(true)
	s.Cell = s.Cell.Foreground(th.Text)
	t.SetStyles(s)
	return t
}

// flexWidth budgets a flexible column: the inner table width minus the fixed
// columns and bubbles/table's 2-cell-per-column padding, floored at min.
func flexWidth(inner, fixedSum, numCols, min int) int {
	w := inner - fixedSum - 2*numCols
	if w < min {
		return min
	}
	return w
}

// columnsFor lays out the columns for a tab at a given inner table width. Column
// titles double as the per-tab header.
func columnsFor(tab Tab, inner int) []table.Column {
	switch tab {
	case TabHome:
		name := 14
		return []table.Column{
			{Title: "", Width: 2},
			{Title: "Source", Width: name},
			{Title: "Detail", Width: flexWidth(inner, 2+name, 3, 8)},
		}
	case TabFacts:
		kind, status := 11, 10
		return []table.Column{
			{Title: "Kind", Width: kind},
			{Title: "Fact", Width: flexWidth(inner, kind+status, 3, 12)},
			{Title: "Status", Width: status},
		}
	case TabSessions:
		date, agent, files := 16, 12, 5
		return []table.Column{
			{Title: "When", Width: date},
			{Title: "Agent", Width: agent},
			{Title: "Files", Width: files},
			{Title: "Session", Width: flexWidth(inner, date+agent+files, 4, 8)},
		}
	case TabHistory:
		kind := 12
		return []table.Column{
			{Title: "Kind", Width: kind},
			{Title: "Summary", Width: flexWidth(inner, kind, 2, 12)},
		}
	case TabSemantic:
		kind, file := 10, 22
		return []table.Column{
			{Title: "Kind", Width: kind},
			{Title: "Name", Width: flexWidth(inner, kind+file, 3, 10)},
			{Title: "File", Width: file},
		}
	case TabSearch:
		source := 9
		return []table.Column{
			{Title: "Source", Width: source},
			{Title: "Result", Width: flexWidth(inner, source, 2, 12)},
		}
	default:
		return []table.Column{{Title: "", Width: max(inner-2, 8)}}
	}
}

// rowsFor builds the table rows for a tab, restricted to the given source
// indices (the filtered view). Cells are truncated to roughly their column
// width; the table re-truncates to the exact width when it renders.
func rowsFor(s Snapshot, tab Tab, indices []int) []table.Row {
	cols := columnsFor(tab, 80)
	rows := make([]table.Row, 0, len(indices))
	for _, i := range indices {
		switch tab {
		case TabHome:
			h := s.Home.Sources[i]
			dot := "○"
			if h.Present {
				dot = "●"
			}
			rows = append(rows, table.Row{dot, truncate(h.Name, cols[1].Width), truncate(h.Detail, cols[2].Width)})
		case TabFacts:
			f := s.Facts[i]
			rows = append(rows, table.Row{
				truncate(orDash(f.Kind), cols[0].Width),
				truncate(oneLine(f.Text), cols[1].Width),
				truncate(orDash(f.Status), cols[2].Width),
			})
		case TabSessions:
			v := s.Sessions[i]
			rows = append(rows, table.Row{
				truncate(v.Created, cols[0].Width),
				truncate(orDash(v.Agent), cols[1].Width),
				fmt.Sprintf("%d", len(v.Files)),
				truncate(shortID(v.ID), cols[3].Width),
			})
		case TabHistory:
			h := s.History[i]
			rows = append(rows, table.Row{
				truncate(orDash(h.Kind), cols[0].Width),
				truncate(oneLine(h.Summary), cols[1].Width),
			})
		case TabSemantic:
			v := s.Semantic[i]
			rows = append(rows, table.Row{
				truncate(orDash(v.Kind), cols[0].Width),
				truncate(orDash(v.Name), cols[1].Width),
				truncate(baseName(v.FilePath), cols[2].Width),
			})
		case TabSearch:
			r := s.Search[i]
			rows = append(rows, table.Row{
				truncate(orDash(r.Source), cols[0].Width),
				truncate(oneLine(r.Text), cols[1].Width),
			})
		}
	}
	return rows
}

package tui

import "github.com/charmbracelet/bubbles/key"

// keyMap is the dashboard keymap. It implements help.KeyMap so bubbles/help can
// render the short and full help views.
type keyMap struct {
	Up      key.Binding
	Down    key.Binding
	Enter   key.Binding
	Back    key.Binding
	Section key.Binding
	PrevTab key.Binding
	Filter  key.Binding
	Search  key.Binding
	Open    key.Binding
	Help    key.Binding
	Quit    key.Binding
}

func defaultKeys() keyMap {
	return keyMap{
		Up:      key.NewBinding(key.WithKeys("up", "k"), key.WithHelp("↑/k", "up")),
		Down:    key.NewBinding(key.WithKeys("down", "j"), key.WithHelp("↓/j", "down")),
		Enter:   key.NewBinding(key.WithKeys("enter", "right", "l"), key.WithHelp("enter/→", "open")),
		Back:    key.NewBinding(key.WithKeys("esc", "left", "h"), key.WithHelp("esc/←", "back")),
		Section: key.NewBinding(key.WithKeys("tab"), key.WithHelp("tab", "next section")),
		PrevTab: key.NewBinding(key.WithKeys("shift+tab"), key.WithHelp("shift+tab", "prev section")),
		Filter:  key.NewBinding(key.WithKeys("/"), key.WithHelp("/", "filter")),
		Search:  key.NewBinding(key.WithKeys("s"), key.WithHelp("s", "search brain")),
		Open:    key.NewBinding(key.WithKeys("o"), key.WithHelp("o", "open source")),
		Help:    key.NewBinding(key.WithKeys("?"), key.WithHelp("?", "help")),
		Quit:    key.NewBinding(key.WithKeys("q", "ctrl+c"), key.WithHelp("q", "quit")),
	}
}

// ShortHelp is the single-line help shown in the footer.
func (k keyMap) ShortHelp() []key.Binding {
	return []key.Binding{k.Up, k.Down, k.Enter, k.Section, k.Filter, k.Search, k.Open, k.Help, k.Quit}
}

// FullHelp is the expanded help shown when ? is toggled.
func (k keyMap) FullHelp() [][]key.Binding {
	return [][]key.Binding{
		{k.Up, k.Down, k.Enter, k.Back},
		{k.Section, k.PrevTab, k.Filter, k.Search},
		{k.Open, k.Help, k.Quit},
	}
}

package tui

import (
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// Theme is the color palette for the dashboard. Themes are selectable via the
// --theme flag (or ENTIRE_BRAIN_THEME); the default is a neutral dark scheme
// that works on any 256-color terminal.
type Theme struct {
	Name    string
	Border  lipgloss.Color // pane borders
	Accent  lipgloss.Color // titles, selected row, active tab
	Text    lipgloss.Color // primary text
	Dim     lipgloss.Color // secondary/muted text
	Good    lipgloss.Color // healthy / fresh / present
	OK      lipgloss.Color // partial / stale
	Bad     lipgloss.Color // missing / failed
	Flag    lipgloss.Color // warnings / superseded
	Link    lipgloss.Color // clickable links
	Heading lipgloss.Color // detail section headings
}

var themes = map[string]Theme{
	"default": {
		Name:    "default",
		Border:  lipgloss.Color("244"),
		Accent:  lipgloss.Color("39"),
		Text:    lipgloss.Color("231"), // bright white
		Dim:     lipgloss.Color("250"), // light gray (still readable)
		Good:    lipgloss.Color("47"),
		OK:      lipgloss.Color("214"),
		Bad:     lipgloss.Color("203"),
		Flag:    lipgloss.Color("220"),
		Link:    lipgloss.Color("45"),
		Heading: lipgloss.Color("39"),
	},
	"catppuccin": {
		Name:    "catppuccin",
		Border:  lipgloss.Color("#6c7086"),
		Accent:  lipgloss.Color("#89b4fa"),
		Text:    lipgloss.Color("#ffffff"), // white
		Dim:     lipgloss.Color("#bac2de"),
		Good:    lipgloss.Color("#a6e3a1"),
		OK:      lipgloss.Color("#f9e2af"),
		Bad:     lipgloss.Color("#f38ba8"),
		Flag:    lipgloss.Color("#fab387"),
		Link:    lipgloss.Color("#89dceb"),
		Heading: lipgloss.Color("#cba6f7"),
	},
	"gruvbox": {
		Name:    "gruvbox",
		Border:  lipgloss.Color("#928374"),
		Accent:  lipgloss.Color("#83a598"),
		Text:    lipgloss.Color("#fbf1c7"), // bright cream-white
		Dim:     lipgloss.Color("#d5c4a1"),
		Good:    lipgloss.Color("#b8bb26"),
		OK:      lipgloss.Color("#fabd2f"),
		Bad:     lipgloss.Color("#fb4934"),
		Flag:    lipgloss.Color("#fe8019"),
		Link:    lipgloss.Color("#8ec07c"),
		Heading: lipgloss.Color("#d3869b"),
	},
	"tokyonight": {
		Name:    "tokyonight",
		Border:  lipgloss.Color("#565f89"),
		Accent:  lipgloss.Color("#7aa2f7"),
		Text:    lipgloss.Color("#ffffff"), // white
		Dim:     lipgloss.Color("#a9b1d6"),
		Good:    lipgloss.Color("#9ece6a"),
		OK:      lipgloss.Color("#e0af68"),
		Bad:     lipgloss.Color("#f7768e"),
		Flag:    lipgloss.Color("#ff9e64"),
		Link:    lipgloss.Color("#7dcfff"),
		Heading: lipgloss.Color("#bb9af7"),
	},
}

// ThemeByName resolves a theme by name (case-insensitive), falling back to the
// default scheme for an empty or unknown name. The bool reports whether the name
// matched a known theme.
func ThemeByName(name string) (Theme, bool) {
	if t, ok := themes[normalizeThemeName(name)]; ok {
		return t, true
	}
	return themes["default"], name == "" || normalizeThemeName(name) == "default"
}

// ThemeNames lists the available theme names (for help text / flag docs).
func ThemeNames() []string {
	return []string{"default", "catppuccin", "gruvbox", "tokyonight"}
}

func normalizeThemeName(name string) string {
	out := make([]rune, 0, len(name))
	for _, r := range name {
		switch {
		case r >= 'A' && r <= 'Z':
			out = append(out, r+('a'-'A'))
		case r == ' ' || r == '-' || r == '_':
			// fold separators so "tokyo night" == "tokyo-night" == "tokyonight"
		default:
			out = append(out, r)
		}
	}
	return string(out)
}

// healthColor maps a source/freshness state to the theme's good/ok/bad color.
// "fresh"/"present"/"ok" are good; "stale"/"partial"/"degraded" are ok; the rest
// (missing, failed, error) are bad.
func (t Theme) healthColor(state string) lipgloss.Color {
	switch normalizeThemeName(state) {
	case "fresh", "present", "ok", "healthy", "clean", "current", "true":
		return t.Good
	case "stale", "partial", "degraded", "warning", "pending":
		return t.OK
	default:
		return t.Bad
	}
}

func (t Theme) titleStyle() lipgloss.Style {
	return lipgloss.NewStyle().Bold(true).Foreground(t.Accent)
}

func (t Theme) headingStyle() lipgloss.Style {
	return lipgloss.NewStyle().Bold(true).Foreground(t.Heading)
}

func (t Theme) dimStyle() lipgloss.Style {
	return lipgloss.NewStyle().Foreground(t.Dim)
}

func (t Theme) textStyle() lipgloss.Style {
	return lipgloss.NewStyle().Foreground(t.Text)
}

func (t Theme) flagStyle() lipgloss.Style {
	return lipgloss.NewStyle().Foreground(t.Flag)
}

func (t Theme) linkStyle() lipgloss.Style {
	return lipgloss.NewStyle().Foreground(t.Link).Underline(true)
}

// osc8 wraps label in an OSC 8 terminal hyperlink so terminals that support it
// (iTerm2, kitty, WezTerm, modern Terminal.app, VS Code) make it cmd/ctrl-click
// to open. Terminals that don't support it just show the label. The escape
// sequences are zero-width, so callers must not pass the result through a
// width-constrained lipgloss style (it would miscount and wrap).
func osc8(url, label string) string {
	if url == "" {
		return label
	}
	return "\x1b]8;;" + url + "\x1b\\" + label + "\x1b]8;;\x1b\\"
}

// fileURL turns an absolute filesystem path into a file:// URL for an OSC 8
// link, or "" for an empty path. Spaces are percent-encoded so the URL stays
// well-formed; other characters are left as-is (paths are local and trusted).
func fileURL(p string) string {
	if p == "" {
		return ""
	}
	return "file://" + strings.ReplaceAll(p, " ", "%20")
}

// paneStyle is a rounded-border pane in the theme's border color (accent when
// focused).
func (t Theme) paneStyle(focused bool) lipgloss.Style {
	color := t.Border
	if focused {
		color = t.Accent
	}
	return lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(color)
}

