func TestResolveDashTheme(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_THEME", "") // isolate from the host env
	// A known theme resolves without error.
	if th, err := resolveDashTheme("gruvbox"); err != nil || th.Name != "gruvbox" {
